const ev = $input.first().json.body;
if (ev.type !== 'package_shipped') return [];
const ship = ev.data.shipment, orderExt = ev.data.order.external_id;
const sbh = { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
const updated = await this.helpers.httpRequest({ method: 'PATCH',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${orderExt}`,
  headers: sbh, json: true,
  body: { status: 'shipped', tracking_number: ship.tracking_number, tracking_url: ship.tracking_url } });
const c = updated[0];
await this.helpers.httpRequest({ method: 'POST', url: 'https://api.resend.com/emails', json: true,
  headers: { Authorization: `Bearer ${$vars.RESEND_KEY}`, 'Content-Type': 'application/json' },
  body: {
    from: 'TOTEHM <totehm@higher.boutique>', to: [c.email],
    subject: `\u3010${c.name}\u3011 has left the atelier.`,
    html: `<p>Your Totehm Cloth \u3010${c.name}\u3011 is on its way.</p><p><a href="${c.tracking_url}">Track it</a></p><p>Do not open it like a package. Open it like a painting.</p><p>\u2014 TOTEHM</p>`,
  }});
return [{ json: { ok: true } }];
